import { createWaitFor } from '../../utils/blueprints/wait-for.js';
import { createTracedFetch } from '../../utils/traced-fetch.js';
import { setupLogPolling } from './logs-polling.js';
import { classifyOperationPoll, getOperation } from './operations.js';
/**
 * Stream logs and poll an operation until it settles.
 * handles log-stream lifecycle, retry budget, and idle messaging;
 * the caller maps the returned outcome to its own result/messaging.
 */
export async function waitForOperation(options) {
    const { stackId, operationId, auth, log, bin, verbose = false, includeDestroyed, progressNoun, } = options;
    const fetchFn = createTracedFetch(log);
    const waitFor = createWaitFor({
        bin,
        log,
        verbose,
    });
    return await waitFor({
        async onRequestLatestState() {
            const { ok, error, operation, response } = await getOperation({
                stackId,
                operationId,
                auth,
                fetchFn,
                includeDestroyed,
            });
            const httpStatus = response?.status;
            const state = classifyOperationPoll({ ok, httpStatus, operation });
            switch (state) {
                case 'completed':
                case 'failed':
                    return {
                        state,
                    };
                case 'error':
                    return {
                        state,
                        error,
                        verboseError: `Could not read ${progressNoun} status (HTTP ${httpStatus ?? 'unknown'}${error ? `: ${error}` : ''})`,
                    };
                case 'pending':
                    if (httpStatus === 404 || !operation) {
                        return {
                            state: 'not_found',
                            verboseError: `Waiting for ${progressNoun} status (HTTP 404); retrying.`,
                        };
                    }
                    else {
                        return {
                            state,
                            latestStatus: operation.status,
                            verboseMessage: `${progressNoun} operation status: ${operation.status}.`,
                        };
                    }
                default:
                    throw new Error(`Unexpected poll state: ${state}`);
            }
        },
        onStartLogPolling(options) {
            return setupLogPolling({
                stackId,
                operationId,
                auth,
                fetchFn,
                onActivity: options.onActivity,
                onLogEntry: options.onLogEntry,
            });
        },
        getIdleMessage() {
            return `The ${progressNoun} is still running on Sanity servers.`;
        },
    });
}
